// ---------- 1. Parse the AI output into a bill object ----------
const aiOut = $input.first().json;
const raw = aiOut.content ?? aiOut.text ?? aiOut.message?.content ?? JSON.stringify(aiOut);

let bill;
const fenced = String(raw).match(/```(?:json)?\s*([\s\S]*?)```/);
try {
  bill = JSON.parse((fenced ? fenced[1] : String(raw)).trim());
} catch (e) {
  const braces = String(raw).match(/\{[\s\S]*\}/);
  if (!braces) throw new Error('Could not parse bill JSON from AI output: ' + String(raw).slice(0, 300));
  bill = JSON.parse(braces[0]);
}

// ---------- 2. Helpers ----------
const num = (v) => {
  const n = typeof v === 'string' ? parseFloat(v.replace(/[^0-9.\-]/g, '')) : Number(v);
  return Number.isFinite(n) ? n : 0;
};
const r2 = (n) => Math.round(n * 100) / 100;
const cur = !bill.currency || bill.currency === 'INR' ? '₹' : bill.currency + ' ';
const fmt = (n) => cur + Number(n).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// ---------- 3. Calculations ----------
const items = (bill.line_items || []).map((it) => {
  const qty = num(it.quantity) || 1;
  const rate = num(it.unit_price);
  const amount = num(it.amount) || r2(qty * rate);
  return { description: it.description || 'Item', qty, rate, amount };
});

const itemsTotal = r2(items.reduce((s, i) => s + i.amount, 0));
const discount = Math.abs(num(bill.discount));
const taxes = (bill.taxes || []).map((t) => ({ name: t.name || 'Tax', rate: num(t.rate_percent), amount: num(t.amount) }));
const taxTotal = r2(taxes.reduce((s, t) => s + t.amount, 0));
const otherCharges = (bill.other_charges || []).map((c) => ({ name: c.name || 'Charge', amount: num(c.amount) }));
const otherTotal = r2(otherCharges.reduce((s, c) => s + c.amount, 0));

const computedTotal = r2(itemsTotal - discount + taxTotal + otherTotal);
const printedTotal = num(bill.grand_total);
const diff = r2(printedTotal - computedTotal);
const totalsMatch = Math.abs(diff) <= 1; // tolerate ₹1 round-off
const taxPctOfItems = itemsTotal > 0 ? r2((taxTotal / itemsTotal) * 100) : 0;

// ---------- 3b. Bifurcation of the bill amount ----------
const SPLIT = [
  { name: 'Kalpana', pct: 20 },
  { name: 'Batra ji', pct: 25 },
  { name: 'Jitender', pct: 25 },
  { name: 'Joshi ji', pct: 30 },
];
const splitBase = printedTotal || computedTotal;
const shares = SPLIT.map((p) => ({ ...p, amount: r2((splitBase * p.pct) / 100) }));
const allocated = r2(shares.reduce((s, p) => s + p.amount, 0));
shares[shares.length - 1].amount = r2(shares[shares.length - 1].amount + r2(splitBase - allocated)); // rounding paise go to the largest share so shares always sum to the bill

// ---------- 4. Build the WhatsApp message ----------
const lines = [];
lines.push(`🧾 *Bill Summary${bill.merchant ? ' — ' + bill.merchant : ''}*`);
const meta = [];
if (bill.bill_date) meta.push('📅 ' + bill.bill_date);
if (bill.invoice_number) meta.push('No: ' + bill.invoice_number);
if (meta.length) lines.push(meta.join('  |  '));
lines.push('');
if (items.length) {
  lines.push(`*Items (${items.length}):*`);
  items.forEach((i, idx) => {
    const qtyPart = i.qty !== 1 || i.rate ? ` — ${i.qty} × ${fmt(i.rate || (i.amount / i.qty))}` : '';
    lines.push(`${idx + 1}. ${i.description}${qtyPart} = ${fmt(i.amount)}`);
  });
  lines.push('');
}
lines.push(`Items total: ${fmt(itemsTotal)}`);
if (discount) lines.push(`Discount: -${fmt(discount)}`);
taxes.forEach((t) => lines.push(`${t.name}${t.rate ? ' @ ' + t.rate + '%' : ''}: ${fmt(t.amount)}`));
if (taxes.length) lines.push(`Total tax: ${fmt(taxTotal)} (${taxPctOfItems}% of items)`);
otherCharges.forEach((c) => lines.push(`${c.name}: ${fmt(c.amount)}`));
lines.push('');
lines.push(`*Grand total (printed): ${fmt(printedTotal)}*`);
lines.push(`Grand total (computed): ${fmt(computedTotal)}`);
lines.push(totalsMatch ? '✅ Totals check out.' : `⚠️ MISMATCH of ${fmt(Math.abs(diff))} — printed total is ${diff > 0 ? 'HIGHER' : 'LOWER'} than the computed one. Please verify the bill.`);
lines.push('');
lines.push(`*Bifurcation of ${fmt(splitBase)}:*`);
shares.forEach((p) => lines.push(`${p.name} (${p.pct}%): ${fmt(p.amount)}`));

const whatsappMessage = lines.join('\n');
const telegramMessage = '✅ Bill processed and summary sent to WhatsApp.\n\n' + whatsappMessage.replace(/\*/g, '');

// ---------- 5. Output ----------
return [{
  json: {
    merchant: bill.merchant,
    bill_date: bill.bill_date,
    invoice_number: bill.invoice_number,
    items,
    itemsTotal,
    discount,
    taxes,
    taxTotal,
    otherCharges,
    printedTotal,
    computedTotal,
    difference: diff,
    totalsMatch,
    splitBase,
    split: shares,
    whatsappMessage,
    telegramMessage
  }
}];
